# 96_order_figure.R: supplementary figure of the three axes of order selection (plotting only; reads 95_order_diagnostics.R tables). Principal pool (shared) for the EPA lakes; BCI has habitat structure only.
suppressPackageStartupMessages({library(ggplot2); library(dplyr); library(tidyr); library(patchwork); library(scales)}); stopifnot(requireNamespace("svglite", quietly = TRUE)); IN <- "revision_random/tables"; OUTF <- "revision_random/figures"
ink <- "#252B2D"; petrol <- "#246878"; orange <- "#C45C19"; sage <- "#79936C"; purple <- "#615A83"; grey <- "#848B8D"; grid_col <- "#E5E9E9"; POOLSEL <- c("bci", "shared")
E <- read.csv(file.path(IN, "order_diagnostics_ecological.csv")) |> filter(pool %in% POOLSEL); C <- read.csv(file.path(IN, "order_diagnostics_compositional.csv")) |> filter(pool %in% POOLSEL); V <- read.csv(file.path(IN, "order_diagnostics_environmental.csv")) |> filter(pool == "shared"); H <- read.csv(file.path(IN, "order_diagnostics_bci_habitat.csv"))
cm <- c("BCI trees (1985)", "EPA macroinvertebrates", "EPA zooplankton"); lv <- function(d) mutate(d, community = factor(community, cm)); E <- lv(E); C <- lv(C); V <- lv(V); H <- lv(H)
disp <- data.frame(community = factor(c("EPA macroinvertebrates", "EPA macroinvertebrates", "EPA zooplankton", "EPA zooplankton"), cm), order = c(2, 5, 2, 4))
base <- theme_minimal(base_size = 8.5, base_family = "sans") + theme(text = element_text(colour = ink), axis.text = element_text(size = 6.8, colour = ink), axis.title = element_text(size = 8, colour = ink), axis.line = element_line(colour = ink, linewidth = .3), axis.ticks = element_line(colour = ink, linewidth = .25), axis.ticks.length = unit(1, "mm"),
  panel.grid.major = element_line(colour = grid_col, linewidth = .25), panel.grid.minor = element_blank(), panel.spacing = unit(3, "mm"), strip.background = element_blank(), strip.text = element_text(size = 7.5, face = "bold", colour = ink), legend.position = "bottom", legend.title = element_blank(), legend.text = element_text(size = 6.8), legend.key.height = unit(2.5, "mm"), legend.key.width = unit(6, "mm"), legend.margin = margin(0, 0, 0, 0), legend.box.spacing = unit(1, "mm"), plot.tag = element_text(size = 11, face = "bold"), plot.margin = margin(2, 3, 1, 2))
sel <- geom_vline(data = disp, aes(xintercept = order), colour = grey, linetype = "dotted", linewidth = .4); xs <- scale_x_continuous(trans = "log2", breaks = c(2, 4, 8, 16, 32, 64, 128, 256, 512), labels = c(2, 4, 8, 16, 32, 64, 128, 256, 512)); fac <- facet_wrap(~community, nrow = 1, scales = "free_x", drop = FALSE)
long <- function(d, cols, labs) d |> select(community, order, all_of(cols)) |> pivot_longer(all_of(cols), names_to = "k", values_to = "v") |> mutate(k = factor(labs[k], unname(labs)))
p1 <- ggplot(long(E, c("retention_rate_incidence_per_order", "retention_rate_relative_per_order"), c(retention_rate_incidence_per_order = "Incidence retention (zeta ratio per order)", retention_rate_relative_per_order = "Relative-abundance retention")), aes(order, v, colour = k, shape = k)) + sel + geom_line(linewidth = .55) + geom_point(size = 1.2) + fac + xs + scale_colour_manual(values = c(petrol, orange)) + labs(tag = "A", y = "Retention rate", x = NULL) + base + theme(axis.title.x = element_blank())
p2 <- ggplot(long(E, c("contribution_weighted_occupancy_similarity_inc", "contribution_weighted_occupancy_dissimilarity_inc", "share_similarity_widespread50_inc", "share_dissimilarity_widespread50_inc"), c(contribution_weighted_occupancy_similarity_inc = "Occupancy, similarity (weighted)", contribution_weighted_occupancy_dissimilarity_inc = "Occupancy, dissimilarity (weighted)", share_similarity_widespread50_inc = "Similarity share, taxa >= 50% of sites", share_dissimilarity_widespread50_inc = "Dissimilarity share, taxa >= 50% of sites")), aes(order, v, colour = k, linetype = k)) + sel + geom_line(linewidth = .55) + fac + xs +
  scale_colour_manual(values = c(petrol, orange, sage, purple)) + scale_linetype_manual(values = c("solid", "solid", "42", "42")) + scale_y_continuous(limits = c(0, 1)) + labs(y = "Occupancy / widespread-taxon share", x = NULL) + base + theme(strip.text = element_blank(), axis.title.x = element_blank()) + guides(colour = guide_legend(nrow = 2))
p3 <- ggplot(long(C, c("sharing_probability", "prop_saturated_component_total"), c(sharing_probability = "P(share >= 1 taxon)", prop_saturated_component_total = "Proportion saturated responses")), aes(order, v, colour = k, linetype = k)) + sel + geom_line(linewidth = .55) + geom_point(size = .9) + geom_hline(yintercept = .10, colour = grey, linewidth = .3, linetype = "dashed") + fac + xs + scale_colour_manual(values = c(petrol, orange)) + scale_linetype_manual(values = c("solid", "42")) + labs(tag = "B", y = "Probability / proportion", x = NULL) + base + theme(strip.text = element_blank(), axis.title.x = element_blank())
p4 <- ggplot(long(C |> filter(order <= 640), c("var_response_component_total", "var_response_component_occupancy", "var_response_component_heterogeneity"), c(var_response_component_total = "Total", var_response_component_occupancy = "Occupancy-associated", var_response_component_heterogeneity = "Abundance heterogeneity")) |> mutate(v = pmax(v, 1e-9)), aes(order, v, colour = k)) + sel + geom_line(linewidth = .55) + fac + xs + scale_y_log10(labels = label_log(digits = 1)) + scale_colour_manual(values = c(purple, petrol, orange)) + labs(y = "Response variance", x = NULL) + base + theme(strip.text = element_blank(), axis.title.x = element_blank())
Vl <- V |> select(community, order, `Max VIF` = max_VIF, `|cor| TP spread vs TP position` = cor_TP_spread_TP_position) |> pivot_longer(-c(community, order), names_to = "k", values_to = "v") |> mutate(v = abs(v)); Vl <- bind_rows(Vl, data.frame(community = factor("BCI trees (1985)", cm), order = 2, k = "Max VIF", v = NA_real_))
note_bci <- data.frame(community = factor("BCI trees (1985)", cm), order = 2, v = 1, lab = "No continuous\nenvironmental\npredictors")
p5 <- ggplot(Vl, aes(order, v, colour = k)) + sel + geom_line(linewidth = .55, na.rm = TRUE) + geom_point(size = 1.2) + geom_text(data = note_bci, aes(order, 2.5, label = lab), inherit.aes = FALSE, size = 2.2, colour = grey, hjust = 0) + facet_wrap(~community, nrow = 1, scales = "free", drop = FALSE) + scale_x_continuous(breaks = c(2, 4, 6, 8, 12, 16, 20)) + scale_colour_manual(values = c(purple, petrol)) + labs(tag = "C", y = "Collinearity", x = NULL) + base + theme(strip.text = element_blank(), axis.title.x = element_blank())
Cl <- V |> select(community, order, `Common spread intervals (matched TP contrast)` = n_valid_common_intervals, `Profiles at widest interval` = widest_interval_n_profiles) |> pivot_longer(-c(community, order), names_to = "k", values_to = "v") |> mutate(v = ifelse(is.na(v), 0, v)); Cl <- bind_rows(Cl, data.frame(community = factor("BCI trees (1985)", cm), order = 2, k = "Profiles at widest interval", v = NA_real_))
p6 <- ggplot(Cl, aes(order, v + 1, colour = k)) + sel + geom_line(linewidth = .55, na.rm = TRUE) + geom_point(size = 1.2, na.rm = TRUE) + facet_wrap(~community, nrow = 1, scales = "free", drop = FALSE) + scale_x_continuous(breaks = c(2, 4, 6, 8, 12, 16, 20)) + scale_y_log10(breaks = c(1, 2, 11, 101), labels = c("0", "1", "10", "100")) + scale_colour_manual(values = c(orange, sage)) + labs(y = "Support (count)", x = "Zeta order, k") + base + theme(strip.text = element_blank())
Hb <- ggplot(H, aes(order, prob_set_spans_two_or_more_habitats)) + sel + geom_line(colour = sage, linewidth = .55) + facet_wrap(~community, nrow = 1, scales = "free_x", drop = FALSE) + xs + labs(y = "BCI habitat: P(set spans >= 2 classes)", x = NULL) + base + theme(strip.text = element_blank())
fig <- (p1 / p2 / p3 / p4 / p5 / p6) + plot_layout(heights = c(1, 1.1, 1, 1, 1, 1.15)); for (ext in c("pdf", "svg", "png")) ggsave(file.path(OUTF, paste0("FigureS_order_selection_diagnostics.", ext)), fig, width = 183, height = 235, units = "mm", dpi = 600, bg = "white", device = switch(ext, pdf = grDevices::cairo_pdf, svg = svglite::svglite, png = "png"))
for (ext in c("pdf", "png")) ggsave(file.path(OUTF, paste0("FigureS_order_selection_BCI_habitat.", ext)), Hb, width = 183, height = 50, units = "mm", dpi = 300, bg = "white", device = switch(ext, pdf = grDevices::cairo_pdf, png = "png"))
# Notes: dotted vertical lines mark the orders displayed in Figure 6 (EPA). Dashed horizontal line in B: sharing-probability threshold 0.10. BCI has no continuous environmental predictors in the final analysis (panels C: EPA only; the BCI column shows axis only).
